#!/usr/bin/env node
const fs = require('node:fs');
const path = require('node:path');

const root = path.resolve(__dirname, '..');
const representativesFile = path.join(root, 'data', 'art-movement-representatives.json');
const artists = require('../data/artists.json').artists;
const artistMap = new Map(artists.map(artist => [artist.id, artist]));
const entries = [];

function appendArtist(categoryId, artistEntry) {
  let entry = entries.find(item => item.categoryId === categoryId);
  if (!entry) {
    entry = {categoryId, artists:[]};
    entries.push(entry);
  }
  entry.artists.push(artistEntry);
}

function workFromArtist(artist, workId) {
  const work = (artist.works || []).find(item => item.id === workId);
  if (!work) throw new Error(`${artist.id}: work ${workId} is missing`);
  return {
    id: work.id,
    title: work.title,
    year: work.year,
    yearLabel: work.yearLabel || String(work.year ?? '연도 미상'),
    ...(work.thumbnail && fs.existsSync(path.join(root, work.thumbnail)) ? {localImage: work.thumbnail} : {})
  };
}

function addExisting(categoryId, artistId, workId, selectionReason, description, options = {}) {
  const artist = artistMap.get(artistId);
  if (!artist) throw new Error(`${artistId}: artist is missing`);
  appendArtist(categoryId, {
    artist:{id:artist.id,name:artist.name,birth:artist.birth,death:artist.death,nationality:artist.nationality},
    work:workFromArtist(artist, workId), selectionReason, description, ...options
  });
}

function addKnown(categoryId, artistId, work, selectionReason, description, options = {}) {
  const artist = artistMap.get(artistId);
  if (!artist) throw new Error(`${artistId}: artist is missing`);
  appendArtist(categoryId, {
    artist:{id:artist.id,name:artist.name,birth:artist.birth,death:artist.death,nationality:artist.nationality},
    work, selectionReason, description, ...options
  });
}

function addNew(categoryId, id, ko, en, birth, death, nationalityKo, nationalityEn, workId, titleKo, titleEn, year, yearLabel, selectionReason, description, options = {}) {
  appendArtist(categoryId, {
    artist:{id,name:{ko,en},birth,death,nationality:{ko:nationalityKo,en:nationalityEn}},
    work:{id:workId,title:{ko:titleKo,en:titleEn},year,yearLabel},
    selectionReason, description, ...options
  });
}

addNew('renaissance--early','artist-further-botticelli','산드로 보티첼리','Sandro Botticelli',1445,1510,'이탈리아','Italian','botticelli-birth-of-venus','비너스의 탄생','The Birth of Venus',1485,'1484-1486','보티첼리는 초기 르네상스의 인문주의가 고대 신화와 새로운 미의식으로 확장되는 과정을 보여 준다.','고전 신화의 비너스를 맑은 윤곽과 균형 잡힌 화면에 배치한 점에서 르네상스의 고대 부흥이 드러난다. 해부학적 자연스러움보다 유려한 선과 시적인 리듬을 앞세운 것이 보티첼리만의 특징이다.');
addKnown('renaissance--high','artist-Q5592',{id:'michelangelo-creation-of-adam',title:{ko:'아담의 창조',en:'The Creation of Adam'},year:1512,yearLabel:'1508-1512'},'미켈란젤로는 전성기 르네상스가 추구한 이상적 인체와 장대한 종합을 벽화 규모로 확인하게 한다.','정확한 해부학과 안정된 인물 배치는 전성기 르네상스의 인간 중심 질서를 드러낸다. 조각가다운 육중한 신체와 손끝 사이의 긴장으로 정신적 에너지를 만든 점은 미켈란젤로만의 특성이다.');
addExisting('renaissance--venetian','artist-Q17169','wikidata-Q1131110','벨리니는 베네치아 르네상스의 빛과 색채 전통을 티치아노 이전 단계에서 이해하게 한다.','부드러운 빛과 대기 속에 인물과 풍경을 연결한 점에서 베네치아 회화의 색채적 통일이 드러난다. 종교 장면을 조용하고 명상적인 분위기로 바꾼 것이 벨리니만의 특징이다.');
addExisting('northern-renaissance--early-netherlandish','artist-Q68631','rogier-descent-from-cross','반 데르 베이던은 초기 네덜란드 회화의 세밀함이 강한 감정 표현과 결합하는 방식을 보여 준다.','옷감과 눈물의 정밀한 묘사는 북방 르네상스의 관찰력을 드러낸다. 인물들의 몸을 활처럼 연결해 집단적 비탄을 하나의 리듬으로 만든 점은 반 데르 베이던만의 특성이다.');
addExisting('northern-renaissance--german','artist-Q191748','cranach-martin-luther-1528','크라나흐는 독일 르네상스가 종교개혁과 초상 문화에 밀접하게 연결된 양상을 보여 준다.','선명한 윤곽과 세부 묘사는 독일 르네상스의 그래픽한 성격을 드러낸다. 루터의 이미지를 반복 제작해 종교개혁의 시각적 정체성을 만든 점은 크라나흐만의 특징이다.');
addExisting('mannerism--italian','artist-Q9348','parmigianino-madonna-long-neck-1534-1540','파르미자니노는 매너리즘의 의도적인 신체 변형을 가장 알아보기 쉽게 보여 준다.','길어진 목과 손가락, 불안정한 공간은 르네상스의 자연스러운 비례를 세련되게 비튼 매너리즘의 특징이다. 우아함을 현실성보다 앞세워 차갑고 귀족적인 아름다움을 만든 것이 파르미자니노만의 특성이다.');
addExisting('mannerism--fontainebleau','artist-Q333366','primaticcio-rape-of-helen-1530-1539','프리마티초는 퐁텐블로파의 궁정 장식 체계를 로소 이후 지속한 핵심 화가다.','늘씬한 인체와 복잡한 신화 장면은 프랑스 궁정에서 전개된 매너리즘의 특징을 보여 준다. 회화·스투코·실내 장식을 하나의 프로그램으로 통합한 점은 프리마티초만의 강점이다.');
addExisting('baroque--italian','artist-Q160538','bernini-ecstasy-of-saint-teresa-1647-1652','베르니니는 이탈리아 바로크가 회화뿐 아니라 조각과 건축을 통해 관람자를 끌어들이는 방식을 보여 준다.','빛과 대각선, 격렬한 몸짓으로 종교 체험을 현재의 사건처럼 만든 점에서 바로크의 극성이 드러난다. 조각·건축·숨은 채광을 한 무대로 결합한 것이 베르니니만의 특성이다.');
addExisting('baroque--flemish','artist-Q150679','van-dyck-charles-i-at-the-hunt-1635','반 다이크는 플랑드르 바로크의 풍부한 붓질이 국제 궁정 초상으로 확장되는 과정을 보여 준다.','유연한 붓질과 화려한 직물은 플랑드르 바로크의 감각성을 드러낸다. 인물을 가늘고 우아하게 보이게 하면서 권위를 자연스럽게 연출한 점은 반 다이크만의 특성이다.');
addExisting('baroque--dutch-golden-age','artist-Q41264','wikidata-Q700251','페르메이르는 네덜란드 황금기의 시민적 실내와 빛의 질서를 집중해서 볼 수 있게 한다.','일상의 작은 실내와 창으로 들어오는 빛은 네덜란드 장르화의 특징을 드러낸다. 고요한 순간을 정교한 색면과 광학적 빛으로 영원한 장면처럼 만든 것이 페르메이르만의 특성이다.');
addExisting('baroque--spanish','artist-Q209615','zurbaran-saint-serapion-1628','수르바란은 스페인 바로크의 신앙적 엄숙함과 물질적 사실성을 선명하게 보여 준다.','어두운 배경과 강한 빛, 거친 흰 수도복은 스페인 바로크의 절제된 극성을 드러낸다. 과장된 행동 없이 정물처럼 고요한 인물로 순교의 무게를 전달한 점은 수르바란만의 특성이다.');
addExisting('baroque--french','artist-Q170170','le-brun-queens-of-persia-at-the-feet-of-alexander-1660-1661','르브룅은 프랑스 바로크가 왕실의 권위와 아카데미의 규범으로 조직되는 방식을 보여 준다.','명료한 서사와 통제된 감정은 프랑스 바로크의 고전주의적 질서를 드러낸다. 여러 예술가를 지휘해 왕권의 이미지를 종합적으로 설계한 점은 르브룅만의 특성이다.');
addNew('realism--french','artist-further-millet','장프랑수아 밀레','Jean-Francois Millet',1814,1875,'프랑스','French','millet-the-gleaners','이삭 줍는 여인들','The Gleaners',1857,'1857','밀레는 프랑스 사실주의가 농민의 반복 노동을 역사화만큼 중요한 주제로 다루게 한 화가다.','낮게 숙인 노동자의 몸과 넓은 들판은 이상화되지 않은 농촌 현실을 보여 준다. 사회 비판을 직접 외치기보다 묵직한 형태와 황혼빛으로 노동의 존엄과 피로를 함께 전달한 점은 밀레만의 특성이다.');
addNew('realism--russian','artist-further-kramskoi','이반 크람스코이','Ivan Kramskoi',1837,1887,'러시아','Russian','kramskoi-christ-in-the-desert','광야의 그리스도','Christ in the Desert',1872,'1872','크람스코이는 이동파의 사실주의가 종교적 인물을 동시대 인간의 윤리적 갈등으로 바꾸는 방식을 보여 준다.','황량한 풍경과 지친 자세는 러시아 사실주의의 심리적·사회적 진실 추구를 드러낸다. 극적 기적 대신 침묵과 내적 선택에 집중한 점은 크람스코이만의 특성이다.');
addNew('post-impressionism--core','artist-further-cezanne','폴 세잔','Paul Cezanne',1839,1906,'프랑스','French','cezanne-mont-sainte-victoire','생트빅투아르산','Mont Sainte-Victoire',1904,'1902-1906','세잔은 후기인상주의가 순간의 빛에서 화면의 구조로 이동하는 축을 보여 준다.','색조의 반복으로 산과 들을 단단한 덩어리처럼 구성한 점에서 후기인상주의의 구조적 탐구가 드러난다. 자연을 원통·구·원뿔에 가까운 관계로 다시 조직한 것이 세잔만의 특성이다.');
addNew('post-impressionism--neo-impressionism','artist-further-signac','폴 시냐크','Paul Signac',1863,1935,'프랑스','French','signac-port-saint-tropez','생트로페 항구','The Port of Saint-Tropez',1901,'1901','시냐크는 신인상주의의 분할 색채 이론을 풍경과 항구 장면으로 확산한 중심 화가다.','서로 섞지 않은 색점이 관람자의 눈에서 빛으로 합쳐지는 점은 신인상주의의 특징이다. 쇠라보다 크고 자유로운 모자이크 같은 붓질로 화면에 밝은 장식성을 더한 것이 시냐크만의 특성이다.');
addNew('post-impressionism--pont-aven-synthetism','artist-further-emile-bernard','에밀 베르나르','Emile Bernard',1868,1941,'프랑스','French','bernard-breton-women-meadow','목초지의 브르타뉴 여인들','Breton Women in a Meadow',1888,'1888','베르나르는 퐁타방파의 굵은 윤곽과 평평한 색면 형성에 직접 기여한 화가다.','검은 윤곽과 단순한 색면은 관찰보다 기억과 상징을 종합하는 이 사조의 특징을 드러낸다. 브르타뉴의 일상을 스테인드글라스처럼 평면화한 클루아조니슴이 베르나르만의 핵심 특성이다.');
addNew('expressionism--brucke','artist-further-heckel','에리히 헤켈','Erich Heckel',1883,1970,'독일','German','heckel-glassy-day','유리처럼 맑은 날','Glassy Day',1913,'1913','헤켈은 다리파의 거친 목판화적 형태가 풍경과 누드에 적용되는 방식을 보여 준다.','각진 신체와 비자연적인 색은 외형보다 정서적 긴장을 앞세우는 다리파의 특징을 드러낸다. 날카롭게 깎인 면과 차가운 색으로 고독한 분위기를 만든 점은 헤켈만의 특성이다.');
addNew('expressionism--blue-rider','artist-further-franz-marc','프란츠 마르크','Franz Marc',1880,1916,'독일','German','marc-blue-horse-i','푸른 말 I','Blue Horse I',1911,'1911','마르크는 청기사파가 색에 정신적 의미를 부여한 방식을 동물 이미지로 이해하게 한다.','현실과 다른 파랑·노랑·빨강을 감정과 정신의 언어로 사용한 점에서 청기사파의 특징이 드러난다. 인간 대신 동물을 순수한 생명과 자연의 상징으로 삼은 것이 마르크만의 특성이다.');
addNew('expressionism--austrian','artist-further-kokoschka','오스카 코코슈카','Oskar Kokoschka',1886,1980,'오스트리아','Austrian','kokoschka-bride-of-wind','바람의 신부','The Bride of the Wind',1914,'1913-1914','코코슈카는 오스트리아 표현주의의 불안한 심리가 초상과 관계의 서사에 나타나는 방식을 보여 준다.','요동치는 붓질과 뒤틀린 공간은 내면의 불안을 외형보다 앞세우는 이 사조의 특징을 드러낸다. 인물 사이의 감정적 긴장을 피부와 배경 전체의 운동으로 확장한 점은 코코슈카만의 특성이다.');
addNew('cubism--analytic','artist-further-braque','조르주 브라크','Georges Braque',1882,1963,'프랑스','French','braque-violin-and-palette','바이올린과 팔레트','Violin and Palette',1909,'1909','브라크는 피카소와 함께 분석적 입체주의의 분절된 시점을 발전시킨 공동 창안자다.','사물을 작은 면으로 해체하고 갈색·회색의 제한된 색조로 재조립한 점에서 분석적 입체주의가 드러난다. 악기와 문자 단서를 남겨 추상과 현실 인식 사이의 균형을 잡은 것이 브라크만의 특성이다.');
addKnown('cubism--synthetic','artist-art-atlas-picasso',{id:'picasso-three-musicians',title:{ko:'세 명의 음악가',en:'Three Musicians'},year:1921,yearLabel:'1921'},'피카소는 분석적 입체주의에서 종합적 입체주의로 이동하며 평면 조각과 색면의 가능성을 확장했다.','큰 색면과 종이를 오린 듯한 형태는 분해보다 결합을 앞세우는 종합적 입체주의의 특징을 드러낸다. 인물과 악기를 유희적인 가면극으로 바꾼 점은 피카소만의 특성이다.',{otherMovements:['분석적 입체주의'],duplicateArtistReason:'피카소는 분석적 입체주의의 형성과 종합적 입체주의의 확장 모두를 설명하는 핵심 화가다.'});
addNew('russian-avant-garde--suprematism','artist-further-lissitzky','엘 리시츠키','El Lissitzky',1890,1941,'러시아','Russian','lissitzky-proun-19d','프로운 19D','Proun 19D',1922,'1920-1921','리시츠키는 절대주의의 기하학을 건축적 공간과 디자인으로 확장한 화가다.','순수 기하 형태가 중력과 원근의 기준 없이 떠 있는 점에서 절대주의의 비대상성이 드러난다. 이를 실제 공간과 인쇄 디자인으로 연결한 프로운 개념은 리시츠키만의 특성이다.',{otherMovements:['구성주의']});
addNew('russian-avant-garde--constructivism','artist-further-tatlin','블라디미르 타틀린','Vladimir Tatlin',1885,1953,'러시아','Russian','tatlin-monument-third-international','제3인터내셔널 기념탑 모형','Monument to the Third International',1920,'1919-1920','타틀린은 구성주의가 자율적 회화에서 재료·기술·사회적 기능으로 이동한 기준점이다.','철과 유리의 구조, 회전하는 내부 공간은 예술과 공학의 결합이라는 구성주의의 특징을 드러낸다. 재료 자체의 성질에서 형태를 출발시키고 혁명 사회의 통신 장치를 구상한 점은 타틀린만의 특성이다.');
addNew('dada--zurich','artist-further-arp','장 아르프','Jean Arp',1886,1966,'프랑스·독일','French-German','arp-collage-squares-laws-chance','우연의 법칙에 따라 배열한 사각형 콜라주','Collage with Squares Arranged According to the Laws of Chance',1917,'1916-1917','아르프는 취리히 다다가 이성적 통제 대신 우연을 창작 원리로 삼은 방식을 보여 준다.','찢은 종이가 우연히 떨어진 배열을 받아들인 점에서 다다의 반합리성이 드러난다. 이후 유기적 추상 형태로 우연과 자연 성장의 감각을 이어 간 것이 아르프만의 특성이다.');
addNew('dada--berlin','artist-further-hausmann','라울 하우스만','Raoul Hausmann',1886,1971,'오스트리아·독일','Austrian-German','hausmann-mechanical-head','기계적 머리','Mechanical Head',1920,'1919-1920','하우스만은 베를린 다다의 정치적 풍자와 포토몽타주 정신을 입체 오브제로 보여 준다.','일상 물건을 인간 두상에 부착해 합리적 인간이라는 믿음을 조롱한 점에서 베를린 다다의 비판성이 드러난다. 인간의 정체성이 외부 정보와 기계에 의해 조립된다는 발상이 하우스만만의 특성이다.');
addNew('dada--new-york','artist-further-man-ray','만 레이','Man Ray',1890,1976,'미국','American','man-ray-gift','선물','Gift',1921,'1921','만 레이는 뉴욕 다다가 일상 물건의 기능을 뒤집어 예술의 정의를 묻는 방식을 확장했다.','다리미에 못을 붙여 익숙한 물건을 사용할 수 없게 만든 점에서 다다의 전복성이 드러난다. 사진의 레이오그래프와 오브제를 넘나든 실험성이 만 레이만의 특성이다.',{otherMovements:['초현실주의']});
addNew('abstract-expressionism--action-painting','artist-further-de-kooning','윌럼 드 쿠닝','Willem de Kooning',1904,1997,'네덜란드·미국','Dutch-American','de-kooning-woman-i','여인 I','Woman I',1952,'1950-1952','드 쿠닝은 액션 페인팅의 격렬한 붓질이 인체 이미지와 공존할 수 있음을 보여 준다.','긁고 덧칠한 흔적과 반복 수정은 제작 행위 자체를 드러내는 액션 페인팅의 특징이다. 추상과 인물 형상을 끝까지 긴장 관계에 둔 것이 드 쿠닝만의 특성이다.');
addNew('abstract-expressionism--color-field','artist-further-newman','바넷 뉴먼','Barnett Newman',1905,1970,'미국','American','newman-vir-heroicus-sublimis','비르 헤로이쿠스 수블리미스','Vir Heroicus Sublimis',1951,'1950-1951','뉴먼은 색면회화가 거대한 단색장과 최소한의 수직선으로 숭고한 경험을 만드는 방식을 보여 준다.','넓은 붉은 색면이 관람자의 시야를 감싸는 점에서 색면회화의 몰입성이 드러난다. 화면을 가르는 집이라 부른 수직 띠로 색의 연속성과 인간적 척도를 동시에 만든 것이 뉴먼만의 특성이다.');
addNew('pop-art--british','artist-further-paolozzi','에두아르도 파올로치','Eduardo Paolozzi',1924,2005,'영국','British','paolozzi-rich-man-plaything','나는 부자의 노리개였다','I Was a Rich Man’s Plaything',1947,'1947','파올로치는 영국 팝아트가 미국 대중매체 이미지를 비판적으로 수집하기 시작한 초기 단계를 보여 준다.','잡지 광고와 만화, 소비재 이미지를 콜라주한 점에서 팝아트의 대중문화 수용이 드러난다. 매혹과 불안을 동시에 남기는 기계적 파편의 조합은 파올로치만의 특성이다.');
addNew('pop-art--american','artist-further-lichtenstein','로이 리히텐슈타인','Roy Lichtenstein',1923,1997,'미국','American','lichtenstein-whaam','꽝!','Whaam!',1963,'1963','리히텐슈타인은 미국 팝아트가 만화의 인쇄 언어를 대형 회화로 전환한 방식을 보여 준다.','굵은 윤곽, 원색, 벤데이 점은 대량 인쇄 이미지를 미술관 규모로 확대하는 팝아트의 특징이다. 손으로 그렸지만 기계 인쇄처럼 보이게 해 독창성과 복제의 경계를 묻는 점은 리히텐슈타인만의 특성이다.');
addNew('postmodernism--appropriation-pictures','artist-further-levine','셰리 레빈','Sherrie Levine',1947,null,'미국','American','levine-after-walker-evans','워커 에번스 이후','After Walker Evans',1981,'1981','레빈은 차용미술이 기존 이미지의 재촬영만으로 저자성과 소유권을 질문할 수 있음을 보여 준다.','유명 사진을 그대로 다시 촬영해 원본과 복제의 위계를 흔든 점에서 픽처스 제너레이션의 특징이 드러난다. 여성 작가의 위치에서 남성 중심 미술사의 권위를 겨냥한 것이 레빈만의 특성이다.');
addNew('postmodernism--neo-expressionism','artist-further-kiefer','안젤름 키퍼','Anselm Kiefer',1945,null,'독일','German','kiefer-margarethe','마르가레테','Margarethe',1981,'1981','키퍼는 신표현주의가 역사적 기억과 물질의 상처를 거대한 회화에 담는 방식을 보여 준다.','거친 표면과 상징적 글자는 감정과 서사를 되살리는 신표현주의의 특징을 드러낸다. 짚·납·재 같은 재료로 독일의 전쟁 기억과 폐허를 물질화한 점은 키퍼만의 특성이다.');
addExisting('rococo--french','artist-Q313122','artist-Q313122-representative-work','부셰는 프랑스 로코코의 관능적 신화화와 궁정 취향을 가장 화려하게 보여 준다.','밝은 파스텔 색과 곡선, 장식적인 누드는 로코코의 우아한 감각을 드러낸다. 현실의 자연보다 연극적이고 호화로운 환상을 밀도 높게 구성한 것이 부셰만의 특성이다.');
addExisting('rococo--venetian','artist-Q161866','artist-Q161866-representative-work','카날레토는 베네치아 로코코 시대의 도시 풍경과 국제 관광 시장을 이해하게 한다.','맑은 빛과 정교한 원근법으로 베네치아의 일상을 장식적이고 개방된 화면으로 만든 점에서 시대적 취향이 드러난다. 실제 도시를 이상적으로 조정한 정밀한 베두타가 카날레토만의 특성이다.');
addExisting('neoclassicism--french','artist-Q161472','artist-Q161472-representative-work','앵그르는 프랑스 신고전주의의 선과 완결된 표면이 19세기까지 이어지는 방식을 보여 준다.','매끈한 표면과 또렷한 윤곽은 신고전주의의 규율을 드러낸다. 정확한 해부학을 의도적으로 늘여 우아함과 관능을 만든 점은 앵그르만의 특성이다.',{otherMovements:['낭만주의와 맞닿은 오리엔탈리즘']});
addExisting('neoclassicism--roman-international','artist-Q312130','artist-Q312130-representative-work','멩스는 로마를 중심으로 고대와 라파엘로의 질서를 되살린 국제 신고전주의의 이론적 중심이다.','명료한 윤곽과 균형 잡힌 신화 장면은 신고전주의의 고대 모범을 드러낸다. 여러 궁정을 오가며 고고학적 이상을 국제적 장식 언어로 확산한 점은 멩스만의 특성이다.');
addNew('romanticism--german','artist-further-runge','필리프 오토 룽게','Philipp Otto Runge',1777,1810,'독일','German','runge-morning','아침','Morning',1808,'1808','룽게는 독일 낭만주의가 자연과 인간 생애를 종교적 상징 체계로 결합하는 방식을 보여 준다.','빛과 식물, 아이의 형상이 우주의 순환을 암시하는 점에서 독일 낭만주의의 정신적 자연관이 드러난다. 색채 이론과 연작 구상을 통해 회화를 종합적 상징 체계로 만든 것이 룽게만의 특성이다.');
addExisting('romanticism--british','artist-romantic-constable','artist-romantic-constable-work','컨스터블은 영국 낭만주의가 실제 농촌 풍경의 날씨와 빛을 세밀하게 관찰한 축을 보여 준다.','변하는 구름과 습기, 일상적 농촌은 자연을 살아 있는 힘으로 보는 낭만주의의 특징을 드러낸다. 야외 유화 습작의 즉흥성을 큰 완성작으로 옮긴 것이 컨스터블만의 특성이다.');
addKnown('romanticism--french','artist-romantic-gericault',{id:'artist-romantic-gericault-work',title:{ko:'메두사호의 뗏목',en:'The Raft of the Medusa'},year:1819,yearLabel:'1818-1819'},'제리코는 프랑스 낭만주의가 동시대의 재난을 거대한 역사화로 바꾸는 출발점을 보여 준다.','대각선으로 치솟는 몸과 폭풍우는 극적 감정과 현재 사건을 중시한 낭만주의의 특징을 드러낸다. 실제 생존자와 시신을 연구해 이상적 영웅 대신 절망과 희망이 뒤엉킨 인간 군상을 만든 점은 제리코만의 특성이다.');
addNew('romanticism--spanish','artist-further-eugenio-lucas','에우헤니오 루카스 벨라스케스','Eugenio Lucas Velazquez',1817,1870,'스페인','Spanish','lucas-condemned-inquisition','종교재판에서 유죄판결을 받은 사람들','The Condemned by the Inquisition',1860,'1860년경','루카스 벨라스케스는 고야 이후 스페인 낭만주의의 어두운 환상과 사회 풍자를 이어 간 화가다.','폭력적 군중과 음울한 분위기는 이성과 질서보다 공포와 억압을 드러내는 스페인 낭만주의의 특징이다. 빠르고 거친 붓질로 장면을 악몽처럼 흐트러뜨린 점은 루카스만의 특성이다.');
addNew('academicism--core','artist-further-cabanel','알렉상드르 카바넬','Alexandre Cabanel',1823,1889,'프랑스','French','cabanel-birth-of-venus','비너스의 탄생','The Birth of Venus',1863,'1863','카바넬은 아카데미즘의 매끈한 기법과 신화적 누드가 살롱의 공인 취향이 된 방식을 보여 준다.','정확한 드로잉과 붓자국 없는 표면, 이상화된 신체는 아카데미즘의 규범을 드러낸다. 관능적 주제를 고전 신화의 권위로 정당화해 대중성과 제도적 성공을 함께 얻은 점은 카바넬만의 특성이다.');
addNew('impressionism--french','artist-further-renoir','피에르오귀스트 르누아르','Pierre-Auguste Renoir',1841,1919,'프랑스','French','renoir-moulin-galette','물랭 드 라 갈레트의 무도회','Dance at Le Moulin de la Galette',1876,'1876','르누아르는 프랑스 인상주의의 빛이 도시인의 여가와 인물 관계에 적용되는 방식을 보여 준다.','야외의 반짝이는 빛과 순간적인 붓질은 인상주의의 시각 경험을 드러낸다. 풍경보다 사람의 피부와 친밀한 사교 장면에 따뜻한 색채를 집중한 것이 르누아르만의 특성이다.');
addNew('impressionism--american','artist-further-cassatt','메리 카사트','Mary Cassatt',1844,1926,'미국·프랑스 활동','American, active in France','cassatt-child-bath','아이의 목욕','The Child’s Bath',1893,'1893','카사트는 미국 인상주의가 프랑스의 색채와 일본 판화 구도를 여성의 일상 경험에 연결한 방식을 보여 준다.','잘린 시점과 밝은 색, 순간적 장면은 인상주의의 특징을 드러낸다. 어머니와 아이의 친밀한 돌봄을 감상적 장식이 아니라 구조가 단단한 현대 생활의 주제로 만든 것이 카사트만의 특성이다.');
addNew('symbolism--french-belgian','artist-further-redon','오딜롱 르동','Odilon Redon',1840,1916,'프랑스','French','redon-cyclops','키클롭스','The Cyclops',1914,'1914년경','르동은 프랑스 상징주의가 꿈과 무의식의 이미지를 내면 세계의 언어로 사용하는 방식을 보여 준다.','현실에 없는 존재와 모호한 서사는 외부 세계보다 관념과 감정을 중시한 상징주의의 특징을 드러낸다. 초기 흑백의 환상에서 후기의 빛나는 파스텔 색채로 이동한 폭넓은 내면 이미지가 르동만의 특성이다.');
addKnown('symbolism--central-northern-european','artist-art-atlas-klimt',{id:'klimt-judith-i',title:{ko:'유디트 I',en:'Judith I'},year:1901,yearLabel:'1901'},'클림트는 중부유럽 상징주의의 심리와 장식성이 빈의 현대 디자인과 만나는 지점을 보여 준다.','금빛 평면과 상징적 무늬는 현실 묘사보다 욕망과 결합의 의미를 앞세우는 상징주의의 특징을 드러낸다. 인체를 모자이크 같은 장식장 속에 감싸는 방식은 클림트만의 특성이다.',{otherMovements:['빈 분리파·아르누보'],duplicateArtistReason:'클림트는 중부유럽 상징주의와 빈 분리파의 장식적 현대성을 함께 대표한다.'});
addNew('art-nouveau--french-belgian','artist-further-guimard','엑토르 기마르','Hector Guimard',1867,1942,'프랑스','French','guimard-paris-metro-entrance','파리 메트로 입구','Paris Metro Entrance',1900,'1900','기마르는 프랑스 아르누보의 유기적 선을 도시의 공공 디자인으로 확산한 건축가다.','식물 줄기처럼 휘는 철제 구조와 통합된 글자는 자연 형태와 생활 환경을 결합한 아르누보의 특징을 드러낸다. 반복 생산된 지하철 입구를 통해 개인 양식을 파리의 도시 정체성으로 만든 점은 기마르만의 특성이다.');
addNew('art-nouveau--vienna-secession','artist-further-koloman-moser','콜로만 모저','Koloman Moser',1868,1918,'오스트리아','Austrian','moser-secession-poster-13','빈 분리파 제13회 전시 포스터','Poster for the 13th Vienna Secession Exhibition',1902,'1902','모저는 빈 분리파가 회화와 그래픽·가구·생활용품을 하나의 디자인 원리로 연결한 방식을 보여 준다.','평평한 기하 무늬와 명료한 타이포그래피는 역사주의 장식에서 벗어난 빈 분리파의 특징을 드러낸다. 빈 공방을 통해 예술과 일상의 경계를 실제 생산으로 좁힌 점은 모저만의 특성이다.');
addNew('fauvism--matisse-chatou','artist-further-derain','앙드레 드랭','Andre Derain',1880,1954,'프랑스','French','derain-charing-cross-bridge','채링크로스 다리','Charing Cross Bridge',1906,'1906','드랭은 샤투에서 마티스와 함께 야수파의 강렬한 보색과 자율적 붓질을 발전시켰다.','현실의 런던 풍경을 주황·파랑·초록의 강한 대비로 바꾼 점에서 야수파의 색채 해방이 드러난다. 짧고 방향성 있는 붓질로 도시 구조와 빛을 동시에 단순화한 것이 드랭만의 특성이다.');
addNew('fauvism--le-havre','artist-further-friesz','오톤 프리에스','Othon Friesz',1879,1949,'프랑스','French','friesz-la-ciotat','라 시오타','La Ciotat',1907,'1907','프리에스는 르아브르 출신 화가들이 야수파의 색을 항구와 남프랑스 풍경에 적용한 양상을 보여 준다.','굵은 윤곽과 고채도 색은 자연색을 넘어선 야수주의의 특징을 드러낸다. 뒤피보다 무게 있는 형태와 구조를 유지해 색채의 격렬함을 단단한 풍경 구성으로 묶은 점은 프리에스만의 특성이다.');
addNew('futurism--italian','artist-further-balla','자코모 발라','Giacomo Balla',1871,1958,'이탈리아','Italian','balla-dynamism-dog-leash','목줄에 묶인 개의 역동성','Dynamism of a Dog on a Leash',1912,'1912','발라는 이탈리아 미래주의가 연속 사진의 원리를 이용해 일상의 움직임을 분석한 방식을 보여 준다.','반복되는 다리와 꼬리는 시간과 속도를 한 화면에 겹치는 미래주의의 특징을 드러낸다. 거대한 기계보다 작은 일상 장면에서도 운동의 리듬을 발견한 점은 발라만의 특성이다.');
addKnown('futurism--russian-cubo','artist-art-atlas-malevich',{id:'malevich-knife-grinder',title:{ko:'칼 가는 사람',en:'The Knife Grinder'},year:1912,yearLabel:'1912-1913'},'말레비치는 러시아 입체미래주의의 분절된 형태와 운동이 절대주의로 넘어가는 연결 고리를 보여 준다.','인체와 기계를 반복되는 기하 면으로 결합한 점에서 입체주의와 미래주의의 혼합이 드러난다. 재현 형상을 점차 순수 기하학으로 밀어붙인 전환은 말레비치만의 특성이다.',{otherMovements:['절대주의'],duplicateArtistReason:'말레비치는 러시아 입체미래주의의 형식 실험을 절대주의의 순수 기하학으로 전환한 연결 인물이다.'});
addNew('de-stijl--core','artist-further-van-doesburg','테오 판 두스뷔르흐','Theo van Doesburg',1883,1931,'네덜란드','Dutch','van-doesburg-counter-composition-v','반구성 V','Counter-Composition V',1924,'1924','판 두스뷔르흐는 데 스틸의 이론과 국제적 확산을 이끈 화가이자 편집자다.','기본색과 직선, 기하학적 관계는 보편적 질서를 추구한 데 스틸의 특징을 드러낸다. 대각선을 도입한 요소주의로 몬드리안의 수직·수평 원칙에 역동성을 더한 점은 판 두스뷔르흐만의 특성이다.');
addNew('bauhaus--core','artist-further-klee','파울 클레','Paul Klee',1879,1940,'스위스·독일 활동','Swiss, active in Germany','klee-red-balloon','붉은 풍선','Red Balloon',1922,'1922','클레는 바우하우스 교육이 색·형태·리듬의 기초 연구와 개인적 상상력을 함께 다룬 방식을 보여 준다.','단순 기하 형태와 체계적인 색 관계는 바우하우스의 조형 교육을 드러낸다. 어린아이의 기호처럼 보이는 선에 음악적 리듬과 시적 이야기를 담은 점은 클레만의 특성이다.',{otherMovements:['청기사파와 표현주의']});
addNew('surrealism--automatist','artist-further-masson','앙드레 마송','Andre Masson',1896,1987,'프랑스','French','masson-automatic-drawing','자동기술 드로잉','Automatic Drawing',1924,'1924','마송은 자동기술이 의식적 계획을 줄이고 무의식의 연상을 선으로 끌어내는 방식을 보여 준다.','끊임없이 이어지는 선에서 형상이 나타났다가 사라지는 점은 자동기술적 초현실주의의 특징을 드러낸다. 모래와 우연한 재료를 더해 신체적 행위와 무의식의 흔적을 결합한 것이 마송만의 특성이다.');
addNew('surrealism--illusionistic','artist-further-magritte','르네 마그리트','Rene Magritte',1898,1967,'벨기에','Belgian','magritte-treachery-images','이미지의 배반','The Treachery of Images',1929,'1929','마그리트는 환영적 초현실주의가 사실적인 묘사와 논리적 모순을 결합하는 방식을 보여 준다.','정확히 그린 파이프와 이를 부정하는 문장은 익숙한 현실의 의미를 흔드는 초현실주의의 특징을 드러낸다. 꿈 같은 붓질보다 언어와 이미지의 관계를 차갑게 질문한 점은 마그리트만의 특성이다.');
addNew('mexican-muralism--core','artist-further-orozco','호세 클레멘테 오로스코','Jose Clemente Orozco',1883,1949,'멕시코','Mexican','orozco-epic-american-civilization','아메리카 문명의 서사','The Epic of American Civilization',1934,'1932-1934','오로스코는 멕시코 벽화운동이 혁명과 문명의 폭력을 비판적으로 바라본 축을 보여 준다.','공공 벽면의 거대한 인물과 역사 서사는 대중 교육을 지향한 벽화운동의 특징을 드러낸다. 혁명을 낙관적으로 찬양하기보다 기계·전쟁·권력의 파괴성을 비극적으로 강조한 점은 오로스코만의 특성이다.');
addNew('social-realism--core','artist-further-reginald-marsh','레지널드 마시','Reginald Marsh',1898,1954,'미국','American','marsh-twenty-cent-movie','20센트 영화','Twenty Cent Movie',1936,'1936','마시는 사회적 사실주의가 대공황기 도시의 군중과 대중 오락을 관찰하는 방식을 보여 준다.','영화관 광고와 빽빽한 인물은 도시 소비문화와 계층 현실을 다루는 사회적 사실주의의 특징을 드러낸다. 고전적 인체 드로잉을 소란스러운 뉴욕 거리의 리듬에 적용한 점은 마시만의 특성이다.');
addNew('socialist-realism--core','artist-further-mukhina','베라 무히나','Vera Mukhina',1889,1953,'소련','Soviet','mukhina-worker-kolkhoz-woman','노동자와 집단농장 여성','Worker and Kolkhoz Woman',1937,'1937','무히나는 사회주의적 사실주의가 이상화된 노동자 집단을 국가적 기념물로 만드는 방식을 보여 준다.','앞으로 내딛는 거대한 남녀와 낫·망치는 집단적 진보를 명료하게 전달하는 이 사조의 특징을 드러낸다. 스테인리스강의 반사와 대각선 운동으로 산업적 현대성을 강조한 점은 무히나만의 특성이다.');
addNew('art-informel--core','artist-further-wols','볼스','Wols',1913,1951,'독일·프랑스 활동','German, active in France','wols-its-all-over','모든 것은 끝났다','It’s All Over',1947,'1946-1947','볼스는 앵포르멜이 기하학적 질서 대신 즉흥적 선과 물질의 흔적을 선택한 초기 사례를 보여 준다.','긁히고 번지는 선과 불안정한 얼룩은 비정형 추상의 특징을 드러낸다. 작은 화면에 미세한 생물·지도 같은 세계를 응축한 점은 볼스만의 특성이다.');
addNew('nouveau-realisme--core','artist-further-arman','아르망','Arman',1928,2005,'프랑스·미국','French-American','arman-poubelle','쓰레기통','Poubelle',1960,'1960','아르망은 누보 레알리슴이 소비사회의 실제 물건을 수집해 현실 자체를 작품으로 삼는 방식을 보여 준다.','버려진 물건을 투명 상자에 축적한 점에서 일상 현실을 직접 전유하는 누보 레알리슴의 특징이 드러난다. 같은 사물을 반복·집적해 소비와 폐기의 양을 시각화한 것이 아르망만의 특성이다.');
addNew('minimalism--core','artist-further-flavin','댄 플래빈','Dan Flavin',1933,1996,'미국','American','flavin-monument-tatlin','V. 타틀린을 위한 기념비','Monument for V. Tatlin',1964,'1964','플래빈은 미니멀리즘이 산업 제품과 실제 공간의 빛을 작품의 재료로 사용할 수 있음을 보여 준다.','표준 형광등의 반복과 단순한 배치는 작가의 손과 환영을 줄이는 미니멀리즘의 특징을 드러낸다. 물체보다 주변 벽과 관람자의 몸을 물들이는 빛의 공간을 만든 점은 플래빈만의 특성이다.');
addNew('conceptual-art--idea-language','artist-further-weiner','로런스 와이너','Lawrence Weiner',1942,2021,'미국','American','weiner-removal-36-square','36×36인치 벽 제거','A 36 x 36 Removal to the Lathing or Support Wall of Plaster or Wallboard from a Wall',1968,'1968','와이너는 개념미술에서 작품의 실행보다 언어로 제시된 아이디어가 우선할 수 있음을 보여 준다.','문장 자체가 작품의 완전한 형태가 된다는 점에서 물질보다 개념을 앞세우는 이 사조의 특징이 드러난다. 작품은 제작·미제작·타인 제작 모두 가능하다고 선언해 저자와 소유의 조건을 연 것이 와이너만의 특성이다.');
addNew('conceptual-art--fluxus','artist-further-yoko-ono','오노 요코','Yoko Ono',1933,null,'일본·미국','Japanese-American','ono-cut-piece','컷 피스','Cut Piece',1964,'1964','오노 요코는 플럭서스의 간단한 지시와 관객 참여가 윤리적 긴장을 만드는 방식을 보여 준다.','관객이 작가의 옷을 자르는 행위는 완성된 물체보다 사건과 참여를 중시하는 플럭서스의 특징을 드러낸다. 취약한 신체와 관객의 책임을 한 지시문 안에서 드러낸 점은 오노만의 특성이다.',{otherMovements:['퍼포먼스 미술·개념미술']});
addNew('op-art--core','artist-further-riley','브리짓 라일리','Bridget Riley',1931,null,'영국','British','riley-current','커런트','Current',1964,'1964','라일리는 옵아트의 시각적 진동을 흑백 선의 정밀한 배열만으로 만들어 낸 화가다.','반복되는 곡선이 움직이고 부풀어 보이는 점에서 망막의 반응을 작품으로 삼는 옵아트의 특징이 드러난다. 단순한 규칙을 손으로 엄밀히 조절해 신체적인 현기증과 리듬을 만든 점은 라일리만의 특성이다.');
addNew('contemporary-art--installation-performance','artist-further-beuys','요제프 보이스','Joseph Beuys',1921,1986,'독일','German','beuys-i-like-america','나는 미국을 좋아하고 미국도 나를 좋아한다','I Like America and America Likes Me',1974,'1974','보이스는 현대 퍼포먼스와 설치가 상징적 행동을 통해 사회적 치유와 정치적 질문을 제기하는 방식을 보여 준다.','작가의 몸·코요테·펠트가 며칠간 관계를 형성한 점에서 작품을 시간과 상황으로 보는 퍼포먼스 미술의 특징이 드러난다. 모든 사람이 사회를 변화시키는 창조자라는 사회적 조각 개념은 보이스만의 특성이다.',{otherMovements:['플럭서스·개념미술']});
addKnown('contemporary-art--new-media-digital','artist-art-atlas-paik',{id:'paik-electronic-superhighway',title:{ko:'전자 초고속도로: 미국 대륙, 알래스카, 하와이',en:'Electronic Superhighway: Continental U.S., Alaska, Hawaii'},year:1995,yearLabel:'1995'},'백남준은 플럭서스의 사건성과 비디오 기술을 결합해 뉴미디어 미술의 핵심 언어를 만든 작가다.','텔레비전 영상과 전자 회로가 공간 전체를 구성하는 점에서 뉴미디어 미술의 기술·시간 기반 특성이 드러난다. 방송 매체를 일방적 전달 수단이 아니라 유희적이고 참여 가능한 조각 재료로 바꾼 점은 백남준만의 특성이다.',{otherMovements:['플럭서스·개념미술'],duplicateArtistReason:'백남준은 플럭서스의 참여적 사건을 비디오와 전자 매체로 확장해 뉴미디어 미술로 연결한 핵심 작가다.'});
addNew('contemporary-art--street-participatory','artist-further-jr','JR','JR',1983,null,'프랑스','French','jr-women-are-heroes','여성들은 영웅이다','Women Are Heroes',2008,'2008-2011','JR은 거리·참여 미술이 지역 주민의 초상을 도시 규모의 공공 이미지로 바꾸는 방식을 보여 준다.','현장에서 촬영한 주민의 얼굴을 건물과 다리에 붙이고 제작 과정에 공동체가 참여한 점에서 참여 미술의 특징이 드러난다. 익명성을 유지하면서도 거대한 눈과 얼굴로 보이지 않던 사람에게 공적 가시성을 돌려주는 것이 JR만의 특성이다.');

