addExisting('renaissance--high','artist-Q5597','wikidata-Q186953','라파엘로는 레오나르도와 미켈란젤로 사이에서 전성기 르네상스의 균형과 명료한 공간 질서를 완성한 핵심 화가다.','건축 원근과 인물 무리가 안정된 반원 구조를 이루어 고전적 조화라는 사조의 특징을 보여 준다. 서로 다른 철학자의 몸짓과 표정을 분명히 구별하면서도 하나의 질서로 묶은 점은 라파엘로만의 특성이다.');
addExisting('renaissance--venetian','artist-Q8459','wikidata-Q930137','조르조네는 베네치아 르네상스가 서사보다 색채와 대기, 시적인 분위기를 앞세우게 한 전환점이다.','인물보다 폭풍 전의 빛과 젖은 풍경이 화면의 의미를 이끄는 점에서 베네치아의 색채적 자연관이 드러난다. 명확한 이야기 대신 음악처럼 암시적인 정서를 만든 것이 조르조네만의 특성이다.');
addExisting('renaissance--venetian','artist-Q9319','tintoretto-miracle-of-the-slave-1548','틴토레토는 베네치아의 색채에 과감한 단축과 대각선 운동을 결합해 후기 르네상스의 극적 전개를 보여 준다.','급강하하는 성인과 소용돌이치는 군중은 안정된 르네상스 구도를 깨고 강한 운동감을 만든다. 빠른 붓질과 무대 조명 같은 명암으로 사건을 눈앞의 충격으로 바꾼 점은 틴토레토만의 특성이다.');
addExisting('renaissance--venetian','artist-Q9440','veronese-wedding-feast-at-cana-1562-1563','베로네세는 베네치아 르네상스의 화려한 색채와 건축적 장관을 대규모 연회 장면으로 확장했다.','밝은 색의 의상과 고전 건축, 수많은 인물이 거대한 화면에서 질서 있게 어우러져 베네치아 회화의 장식성과 개방감을 보여 준다. 종교 장면을 동시대 귀족 축제처럼 연출한 점은 베로네세만의 특성이다.');
addExisting('northern-renaissance--german','artist-Q48319','holbein-ambassadors-1533','홀바인은 독일계 북방 르네상스의 정밀한 관찰이 국제 궁정 초상과 지적 상징으로 확장되는 모습을 보여 준다.','직물과 과학 도구의 세밀한 묘사는 북방 회화의 사실성을 드러낸다. 화면을 비스듬히 볼 때만 나타나는 해골을 넣어 권력과 지식의 허무를 함께 암시한 점은 홀바인만의 특성이다.');
addExisting('mannerism--italian','artist-Q7803','bronzino-venus-cupid-folly-and-time-1544-1545','브론치노는 매너리즘의 세련된 인공성과 복잡한 우의를 피렌체 궁정 회화의 언어로 완성했다.','차갑고 매끈한 피부, 비현실적인 신체 얽힘, 해독하기 어려운 상징은 자연스러운 르네상스 질서에서 벗어난 매너리즘을 보여 준다. 감정을 억제한 보석 같은 표면은 브론치노만의 특성이다.');
addExisting('baroque--italian','artist-Q7824','wikidata-Q283665','안니발레 카라치는 고전적 구성과 자연 관찰을 결합해 카라바조와 다른 이탈리아 바로크의 한 축을 세웠다.','명료한 인체와 극적인 선택의 순간은 르네상스의 균형을 유지하면서도 바로크의 서사적 에너지를 드러낸다. 여러 전통을 선별해 이상적이면서 생동하는 양식으로 통합한 점은 카라치만의 특성이다.');
addExisting('baroque--dutch-golden-age','artist-Q167654','frans-hals-laughing-cavalier-1624','프란스 할스는 네덜란드 황금시대 초상이 순간적인 표정과 자유로운 붓질을 포착할 수 있음을 보여 준다.','시민 계층의 화려한 복식과 자신감 있는 표정은 네덜란드 초상 문화의 특징을 드러낸다. 빠르게 끊어지는 붓질로 웃음과 자세의 생기를 붙잡은 점은 할스만의 특성이다.');
addExisting('baroque--spanish','artist-Q192062','murillo-the-young-beggar-1645-1650','무리요는 스페인 바로크의 종교적 감성과 세비야의 일상 현실을 부드러운 빛으로 연결한 화가다.','누추한 공간과 아이의 때 묻은 발은 현실 관찰을, 따뜻하게 번지는 빛은 인간적 연민을 드러낸다. 가난을 냉혹한 기록이나 과장된 비극 대신 친밀한 정서로 전달한 점은 무리요만의 특성이다.');
addExisting('baroque--french','artist-Q9340','claude-lorrain-embarkation-of-the-queen-of-sheba-1648','클로드 로랭은 프랑스 바로크의 고전주의가 이상적 풍경과 빛의 질서로 전개된 모습을 보여 준다.','항구 건축과 작은 인물들이 떠오르는 태양을 향해 단계적으로 열리며 장대한 공간을 만든다. 서사보다 황금빛 대기와 먼 거리의 감각을 주인공으로 삼은 점은 로랭만의 특성이다.');
addExisting('post-impressionism--core','artist-Q82445','wikidata-Q3607521','툴루즈로트레크는 후기인상주의가 도시의 밤문화와 인쇄 디자인의 평면성으로 확장되는 과정을 보여 준다.','강한 윤곽과 잘린 구도, 인공 조명은 순간적 관찰을 장식적 화면으로 바꾸는 후기인상주의의 특징을 드러낸다. 공연자와 관객의 개별적인 몸짓에서 도시 유흥의 화려함과 소외를 함께 포착한 점은 로트레크만의 특성이다.');
addExisting('rococo--french','artist-Q313898','artist-Q313898-representative-work','프라고나르는 프랑스 로코코의 유희적 사랑과 빠르고 가벼운 붓질을 가장 활기차게 보여 준다.','분홍빛 드레스와 흔들리는 정원, 숨어 있는 연인은 귀족적 놀이와 감각적 쾌락이라는 로코코의 특징을 드러낸다. 소용돌이치는 잎과 빛으로 순간의 장난스러운 속도를 만든 점은 프라고나르만의 특성이다.');
addExisting('rococo--french','artist-Q213163','wikidata-Q18719540','비제 르 브룅은 로코코 말기의 우아한 초상을 여성 화가의 전문적 자기 이미지와 결합했다.','부드러운 색과 자연스러운 미소, 세련된 옷감은 궁정 초상의 우아함을 드러낸다. 자신을 수동적인 모델이 아니라 자신감 있는 창작자로 제시한 점은 비제 르 브룅만의 특성이다.');
addExisting('rococo--venetian','artist-Q235547','artist-Q235547-representative-work','카리에라는 베네치아 로코코의 가볍고 섬세한 감각을 파스텔 초상으로 국제화한 화가다.','부드러운 색가루와 밝은 피부 표현은 로코코의 친밀하고 우아한 취향을 보여 준다. 유화보다 빠르고 휴대하기 쉬운 파스텔을 독립적인 고급 초상 매체로 끌어올린 점은 카리에라만의 특성이다.');
addExisting('neoclassicism--roman-international','artist-Q155733','artist-Q155733-representative-work','카우프만은 로마의 국제적 신고전주의가 여성 화가와 역사화의 새로운 주제로 확장되는 모습을 보여 준다.','고대 복식과 명료한 윤곽, 절제된 몸짓은 신고전주의의 도덕적 서사를 드러낸다. 보석보다 자녀를 가치로 제시하는 여성 주인공을 중심에 놓은 점은 카우프만만의 특성이다.');

addNew('renaissance--early','artist-mid-fra-angelico','프라 안젤리코','Fra Angelico',1395,1455,'이탈리아','Italian','fra-angelico-annunciation-san-marco','수태고지','The Annunciation',1440,'1438-1445','프라 안젤리코는 중세의 금빛 신앙성과 르네상스의 새로운 공간 표현이 공존하는 초기 단계를 보여 준다.','단순한 회랑의 원근과 부드러운 자연광은 성스러운 사건을 인간의 실제 공간에 놓는다. 절제된 색과 고요한 명상성을 끝까지 유지한 점은 프라 안젤리코만의 특성이다.');
addNew('renaissance--early','artist-mid-piero-della-francesca','피에로 델라 프란체스카','Piero della Francesca',1415,1492,'이탈리아','Italian','piero-flagellation','그리스도의 채찍질','The Flagellation of Christ',1460,'1455-1460','피에로는 초기 르네상스의 수학적 원근과 빛의 질서를 가장 엄밀하게 발전시킨 화가다.','건축 공간과 인물의 크기가 정교한 비례로 연결되어 르네상스의 합리적 공간관을 보여 준다. 감정을 절제한 인물을 맑고 균일한 빛 속에 배치한 점은 피에로만의 특성이다.');
addNew('northern-renaissance--early-netherlandish','artist-mid-robert-campin','로베르 캉팽','Robert Campin',1375,1444,'플랑드르','Flemish','campin-merode-altarpiece','메로드 제단화','Merode Altarpiece',1430,'1427-1432','캉팽은 초기 네덜란드 회화가 종교 사건을 당대 시민의 실내와 일상 물건 속에 배치한 출발점을 보여 준다.','촛불·수건·도구를 세밀하게 그리면서 각각에 상징을 부여한 점에서 북방 르네상스의 관찰과 신앙이 결합한다. 좁은 실내를 친밀한 성소로 바꾼 것이 캉팽만의 특성이다.');
addNew('northern-renaissance--early-netherlandish','artist-mid-hans-memling','한스 멤링','Hans Memling',1430,1494,'플랑드르','Flemish','memling-last-judgment','최후의 심판','The Last Judgment',1471,'1467-1471','멤링은 초기 네덜란드 회화의 정밀한 유화 기법이 국제 교역망을 따라 확산된 모습을 보여 준다.','광택 있는 갑옷과 멀리 이어지는 풍경은 북방 회화의 세부 묘사와 공간감을 드러낸다. 격렬한 심판 장면을 우아하고 대칭적인 질서로 정돈한 점은 멤링만의 특성이다.');
addNew('northern-renaissance--german','artist-mid-grunewald','마티아스 그뤼네발트','Matthias Grunewald',1470,1528,'독일','German','grunewald-isenheim-altarpiece','이젠하임 제단화','Isenheim Altarpiece',1515,'1512-1516','그뤼네발트는 독일 르네상스가 이탈리아식 조화와 달리 강렬한 종교 감정과 신체적 고통을 유지한 축을 보여 준다.','뒤틀린 손과 상처 입은 몸, 비현실적인 빛은 신앙 체험을 직접적인 감각으로 전달한다. 병원 제단의 환자에게 고통과 치유를 동시에 말하도록 구성한 점은 그뤼네발트만의 특성이다.');
addNew('baroque--italian','artist-mid-artemisia-gentileschi','아르테미시아 젠틸레스키','Artemisia Gentileschi',1593,1653,'이탈리아','Italian','gentileschi-judith-slaying-holofernes','홀로페르네스의 목을 베는 유디트','Judith Slaying Holofernes',1613,'1612-1613','젠틸레스키는 카라바조의 명암과 극적 사실성을 여성 주인공의 강한 행동으로 확장한 바로크 화가다.','어둠을 가르는 빛과 대각선의 힘은 이탈리아 바로크의 즉각적인 극성을 드러낸다. 유디트와 하녀를 실제로 힘을 쓰는 협력자로 묘사한 점은 젠틸레스키만의 특성이다.');
addNew('baroque--flemish','artist-mid-jacob-jordaens','야코프 요르단스','Jacob Jordaens',1593,1678,'플랑드르','Flemish','jordaens-king-drinks','왕이 마신다','The King Drinks',1638,'1638년경','요르단스는 플랑드르 바로크의 풍부한 색과 육체성이 시민 가정의 축제와 풍속 장면으로 이어진 모습을 보여 준다.','화면을 가득 채운 인물과 음식, 큰 몸짓은 플랑드르 바로크의 감각적 활력을 드러낸다. 신화나 궁정 대신 서민적 웃음과 속담을 장대한 역사화처럼 다룬 점은 요르단스만의 특성이다.');
addNew('baroque--dutch-golden-age','artist-mid-judith-leyster','유디트 레이스테르','Judith Leyster',1609,1660,'네덜란드','Dutch','leyster-self-portrait','자화상','Self-Portrait',1630,'1630년경','레이스테르는 네덜란드 황금시대의 활기찬 장르화와 여성 화가의 전문적 정체성을 함께 보여 준다.','자연스러운 웃음과 순간적인 자세, 자유로운 붓질은 시민적 초상의 생동감을 드러낸다. 작업 중인 자신을 자신감 있게 바라보는 독립 화가로 제시한 점은 레이스테르만의 특성이다.');
addNew('baroque--dutch-golden-age','artist-mid-jacob-van-ruisdael','야코프 판 라위스달','Jacob van Ruisdael',1628,1682,'네덜란드','Dutch','ruisdael-windmill-at-wijk','베이크의 풍차','The Windmill at Wijk bij Duurstede',1670,'1670년경','라위스달은 네덜란드 황금시대 풍경화가 하늘과 국토를 국가적 기억의 주제로 만든 방식을 보여 준다.','낮은 지평선과 거대한 구름, 풍차와 물길은 네덜란드 풍경의 실제 조건을 장엄하게 드러낸다. 날씨와 빛의 변화로 평범한 장소에 심리적 무게를 부여한 점은 라위스달만의 특성이다.');
addNew('baroque--spanish','artist-mid-jusepe-de-ribera','후세페 데 리베라','Jusepe de Ribera',1591,1652,'스페인·나폴리 활동','Spanish, active in Naples','ribera-martyrdom-saint-philip','성 필립보의 순교','The Martyrdom of Saint Philip',1639,'1639','리베라는 카라바조식 명암을 거친 피부와 순교의 육체에 적용해 스페인 바로크의 사실성을 강화했다.','깊은 어둠과 강한 빛, 당겨지는 몸의 무게는 순교 장면을 관람자 앞의 현실로 만든다. 성인의 고통을 이상화하지 않고 늙고 상처 입은 피부로 묘사한 점은 리베라만의 특성이다.');
addNew('baroque--french','artist-mid-georges-de-la-tour','조르주 드 라 투르','Georges de La Tour',1593,1652,'프랑스','French','la-tour-magdalene-smoking-flame','연기 나는 불꽃 앞의 막달레나','Magdalene with the Smoking Flame',1640,'1640년경','라 투르는 프랑스 바로크가 카라바조의 명암을 조용한 명상과 단순한 기하 형태로 바꾼 모습을 보여 준다.','촛불 하나가 얼굴과 해골을 비추며 어둠 속에 집중된 영적 분위기를 만든다. 격렬한 동작 대신 침묵과 정지로 극적 긴장을 만든 점은 라 투르만의 특성이다.');
addNew('realism--french','artist-mid-honore-daumier','오노레 도미에','Honore Daumier',1808,1879,'프랑스','French','daumier-third-class-carriage','삼등 열차','The Third-Class Carriage',1864,'1862-1864','도미에는 프랑스 사실주의가 도시 노동자와 대중교통의 계급 현실을 직접 다루게 한 화가다.','좁은 객차에 지친 승객을 밀집시켜 산업화 시대의 일상을 이상화 없이 보여 준다. 풍자화의 압축된 선과 묵직한 덩어리로 사회 비판을 전달한 점은 도미에만의 특성이다.');
addNew('realism--russian','artist-mid-vasily-surikov','바실리 수리코프','Vasily Surikov',1848,1916,'러시아','Russian','surikov-morning-streltsy-execution','스트렐치 처형의 아침','The Morning of the Streltsy Execution',1881,'1881','수리코프는 러시아 사실주의가 역사적 사건을 영웅 한 명이 아닌 다양한 민중의 감정으로 재구성한 방식을 보여 준다.','처형 전 광장에 모인 군중의 서로 다른 표정은 역사화에 심리적 현실성을 부여한다. 붉은 광장과 수평 군중을 통해 국가 권력과 개인의 비극을 충돌시킨 점은 수리코프만의 특성이다.');
addNew('post-impressionism--pont-aven-synthetism','artist-mid-paul-serusier','폴 세뤼지에','Paul Serusier',1864,1927,'프랑스','French','serusier-the-talisman','부적','The Talisman',1888,'1888','세뤼지에는 퐁타방파의 종합주의가 관찰한 풍경을 자율적인 색면으로 바꾸는 원리를 가장 압축적으로 보여 준다.','강물과 숲이 노랑·초록·주황의 평평한 얼룩으로 단순화되어 재현보다 색의 감각을 앞세운다. 작은 목판 한 장을 나비파의 교육적 기준점으로 만든 점은 세뤼지에만의 특성이다.');
addNew('romanticism--british','artist-mid-william-blake','윌리엄 블레이크','William Blake',1757,1827,'영국','British','blake-ancient-of-days','태고의 존재','The Ancient of Days',1794,'1794','블레이크는 영국 낭만주의가 자연 관찰뿐 아니라 개인적 신화와 환시를 통해 이성과 제도의 한계를 비판한 축을 보여 준다.','불타는 원 안에서 우주를 재는 형상은 숭고와 상상력을 중시한 낭만주의를 드러낸다. 시·판화·채색을 직접 결합한 독자적 양각 인쇄는 블레이크만의 특성이다.');
addNew('academicism--core','artist-mid-jean-leon-gerome','장레옹 제롬','Jean-Leon Gerome',1824,1904,'프랑스','French','gerome-pollice-verso','폴리체 베르소','Pollice Verso',1872,'1872','제롬은 아카데미즘의 정교한 역사 재현과 매끈한 표면이 대중적 스펙터클로 발전한 모습을 보여 준다.','고고학적 세부와 명료한 인체, 극적인 결말 직전의 순간은 아카데미 역사화의 특징을 드러낸다. 사진처럼 설득력 있는 허구의 고대를 구성한 점은 제롬만의 특성이다.');
addNew('impressionism--french','artist-mid-camille-pissarro','카미유 피사로','Camille Pissarro',1830,1903,'프랑스','French','pissarro-boulevard-montmartre-night','밤의 몽마르트르 대로','The Boulevard Montmartre at Night',1897,'1897','피사로는 인상주의 전시를 지속적으로 이끌며 농촌과 도시의 변화하는 빛을 연작으로 관찰한 중심 화가다.','높은 시점과 짧은 붓질이 거리의 불빛과 군중을 하나의 움직이는 대기로 만든다. 동료 세대를 연결하고 같은 장소를 날씨와 시간별로 연구한 점은 피사로만의 특성이다.');
addNew('impressionism--french','artist-mid-edgar-degas','에드가 드가','Edgar Degas',1834,1917,'프랑스','French','degas-dance-class','무용 수업','The Dance Class',1874,'1874','드가는 인상주의의 순간 포착을 야외 풍경이 아니라 도시 실내와 훈련 중인 신체에 적용한 화가다.','잘린 인물과 비대칭 구도는 우연히 본 순간 같은 현대적 시각을 만든다. 발레의 화려한 무대보다 반복 연습과 피로를 관찰한 점은 드가만의 특성이다.');
addNew('impressionism--french','artist-mid-berthe-morisot','베르트 모리조','Berthe Morisot',1841,1895,'프랑스','French','morisot-cradle','요람','The Cradle',1872,'1872','모리조는 인상주의의 빛과 빠른 붓질을 여성의 사적 공간과 돌봄의 경험에 적용한 핵심 화가다.','얇고 밝은 붓질과 흰 커튼이 실내 공기를 떨리게 하며 순간의 친밀함을 포착한다. 당시 여성에게 허용된 생활 영역을 주변적 장면이 아닌 현대성의 주제로 만든 점은 모리조만의 특성이다.');
addNew('impressionism--american','artist-mid-william-merritt-chase','윌리엄 메릿 체이스','William Merritt Chase',1849,1916,'미국','American','chase-idle-hours','한가한 시간','Idle Hours',1894,'1894','체이스는 미국 인상주의가 유럽의 밝은 붓질을 뉴욕 근교의 여가와 미술 교육에 정착시킨 모습을 보여 준다.','햇빛 아래 흰옷과 잔디가 빠른 색채 터치로 이어져 야외 회화의 특징을 드러낸다. 도시 중산층의 여가와 세련된 생활을 자연스러운 순간으로 구성한 점은 체이스만의 특성이다.');
addNew('symbolism--french-belgian','artist-mid-fernand-khnopff','페르낭 크노프','Fernand Khnopff',1858,1921,'벨기에','Belgian','khnopff-caresses','애무','The Caresses',1896,'1896','크노프는 벨기에 상징주의의 폐쇄적이고 수수께끼 같은 심리를 정교한 화면으로 보여 준다.','스핑크스와 인물의 모호한 관계는 외부 현실보다 욕망과 기억의 상징을 앞세운다. 차갑고 매끈한 표면과 반복되는 여성 얼굴로 접근할 수 없는 내면을 만든 점은 크노프만의 특성이다.');
addNew('symbolism--central-northern-european','artist-mid-arnold-bocklin','아르놀트 뵈클린','Arnold Bocklin',1827,1901,'스위스','Swiss','bocklin-isle-of-the-dead','죽음의 섬','Isle of the Dead',1883,'1883','뵈클린은 중부유럽 상징주의가 풍경을 죽음과 기억의 심리적 무대로 바꾼 대표적 화가다.','어두운 바다와 절벽, 작은 배는 특정 신화의 설명 없이도 장례와 고독을 암시한다. 고전적 장소를 꿈에서 반복되는 원형처럼 만든 점은 뵈클린만의 특성이다.');
addNew('art-nouveau--french-belgian','artist-mid-victor-horta','빅토르 오르타','Victor Horta',1861,1947,'벨기에','Belgian','horta-hotel-tassel','호텔 타셀','Hotel Tassel',1893,'1892-1893','오르타는 벨기에 아르누보의 유기적 곡선을 건축 구조와 실내 전체에 통합한 핵심 건축가다.','철제 기둥과 난간, 바닥 무늬가 식물 줄기처럼 이어져 예술과 생활 공간의 통합을 보여 준다. 장식을 표면에 붙이지 않고 구조와 동선 자체로 만든 점은 오르타만의 특성이다.');
addNew('art-nouveau--vienna-secession','artist-mid-josef-hoffmann','요제프 호프만','Josef Hoffmann',1870,1956,'오스트리아','Austrian','hoffmann-stoclet-palace','스토클레 저택','Stoclet Palace',1911,'1905-1911','호프만은 빈 분리파의 장식적 종합이 기하학적 건축과 생활 디자인으로 정리되는 과정을 보여 준다.','직선적 외관과 맞춤 가구·모자이크가 하나의 총체예술을 이루어 분리파의 통합 디자인을 드러낸다. 장식을 엄격한 격자와 재료의 질서로 통제한 점은 호프만만의 특성이다.');
addNew('fauvism--matisse-chatou','artist-mid-maurice-de-vlaminck','모리스 드 블라맹크','Maurice de Vlaminck',1876,1958,'프랑스','French','vlaminck-chatou-bridge','샤투의 다리','The Chatou Bridge',1906,'1906','블라맹크는 야수파가 강렬한 원색과 거친 붓질로 파리 근교 풍경을 감정의 장으로 바꾼 모습을 보여 준다.','빨강·파랑·노랑이 자연색을 벗어나 충돌하며 야수파의 색채 해방을 드러낸다. 물감을 튜브에서 바로 짜낸 듯한 공격적인 붓질은 블라맹크만의 특성이다.');
addNew('rococo--venetian','artist-mid-francesco-guardi','프란체스코 과르디','Francesco Guardi',1712,1793,'베네치아 공화국','Republic of Venice','guardi-cannaregio-canal-venice','베니스의 카나레지오 운하 풍경','View of the Cannaregio Canal in Venice',1770,'1770년경','과르디는 베네치아 로코코의 도시 풍경을 정확한 기록보다 빛과 흔들리는 대기의 인상으로 바꾼 화가다.','비스듬히 열린 운하와 건물, 작은 배와 인물들이 흔들리는 빛 속에서 이어진다. 카날레토의 정밀한 베두타보다 더 빠르고 떨리는 붓질로 베네치아의 대기와 물빛을 붙잡은 점이 과르디의 개성을 잘 보여 준다.');
addNew('expressionism--brucke','artist-mid-schmidt-rottluff','카를 슈미트로틀루프','Karl Schmidt-Rottluff',1884,1976,'독일','German','schmidt-rottluff-houses-at-night','밤의 집들','Houses at Night',1912,'1912','슈미트로틀루프는 다리파의 거친 형태와 비자연적 색채가 도시 풍경을 불안한 정서로 바꾸는 방식을 보여 준다.','기울어진 집과 충돌하는 원색은 외형보다 감정을 앞세운 표현주의의 특징을 드러낸다. 목판을 깎은 듯 단단하고 각진 면으로 공간을 압축한 점은 슈미트로틀루프만의 특성이다.');
addNew('expressionism--blue-rider','artist-mid-gabriele-munter','가브리엘레 뮌터','Gabriele Munter',1877,1962,'독일','German','munter-boating','보트 타기','Boating',1910,'1910','뮌터는 청기사파의 색채 실험이 일상 풍경과 초상에서 어떻게 단순하고 직접적인 화면으로 나타나는지 보여 준다.','검은 윤곽과 넓은 색면은 자연의 외형보다 내적 인상을 전달한다. 장식적 단순함 속에 인물 관계와 장소의 친밀한 기억을 남긴 점은 뮌터만의 특성이다.');
addNew('expressionism--blue-rider','artist-mid-august-macke','아우구스트 마케','August Macke',1887,1914,'독일','German','macke-lady-green-jacket','초록 재킷을 입은 여인','Lady in a Green Jacket',1913,'1913','마케는 청기사파의 정신적 색채를 현대 도시의 산책과 쇼윈도 장면에 밝고 조화롭게 적용했다.','단순한 인물과 투명한 색면이 리듬을 이루어 재현보다 색의 감정을 앞세운다. 칸딘스키나 마르크보다 평온하고 일상적인 현대 생활을 색채의 낙원으로 만든 점은 마케만의 특성이다.');
addNew('expressionism--austrian','artist-mid-richard-gerstl','리하르트 게르스틀','Richard Gerstl',1883,1908,'오스트리아','Austrian','gerstl-laughing-self-portrait','웃는 자화상','Laughing Self-Portrait',1908,'1908','게르스틀은 빈 표현주의가 장식적 표면을 벗어나 불안정한 자아와 격렬한 붓질로 이동한 급진적 축을 보여 준다.','흐트러진 윤곽과 두꺼운 물감, 정면의 웃음은 내면 상태를 외모보다 앞세운다. 짧은 활동 동안 자화상을 심리적 대결의 장으로 만든 점은 게르스틀만의 특성이다.');
addNew('russian-avant-garde--suprematism','artist-mid-olga-rozanova','올가 로자노바','Olga Rozanova',1886,1918,'러시아','Russian','rozanova-green-stripe','초록 줄무늬','Green Stripe',1917,'1917-1918','로자노바는 절대주의의 기하 형태를 순수한 색의 에너지와 거의 비물질적인 화면으로 밀어붙인 화가다.','흰 바탕을 가르는 단일 녹색 띠는 대상도 깊이도 없이 색 자체의 긴장을 드러낸다. 말레비치보다 밝고 감각적인 색채를 절대주의의 중심으로 만든 점은 로자노바만의 특성이다.');
addNew('russian-avant-garde--constructivism','artist-mid-lyubov-popova','류보프 포포바','Lyubov Popova',1889,1924,'러시아','Russian','popova-painterly-architectonic','회화적 건축','Painterly Architectonic',1918,'1917-1918','포포바는 입체주의적 면 분할을 구성주의의 역동적 구조와 생산 디자인으로 연결한 핵심 화가다.','겹치는 색면과 대각선이 실제 건축처럼 힘을 주고받아 구성주의의 구조적 사고를 드러낸다. 회화에서 무대·직물·인쇄로 이동해 예술과 생산을 연결한 점은 포포바만의 특성이다.');
addNew('russian-avant-garde--constructivism','artist-mid-varvara-stepanova','바르바라 스테파노바','Varvara Stepanova',1894,1958,'러시아','Russian','stepanova-billiard-players','당구 선수들','The Billiard Players',1920,'1920','스테파노바는 구성주의의 기하학을 새로운 인간의 운동과 의복·그래픽 디자인에 적용한 화가다.','원통과 각진 면으로 단순화한 인물은 기계 시대의 속도와 집단적 활동을 보여 준다. 실험 회화를 실제 노동복과 대량생산 디자인으로 전환한 점은 스테파노바만의 특성이다.');
addNew('dada--berlin','artist-mid-george-grosz','게오르게 그로스','George Grosz',1893,1959,'독일·미국','German-American','grosz-pillars-of-society','사회의 기둥들','Pillars of Society',1926,'1926','그로스는 베를린 다다의 파편화와 풍자를 바이마르 사회의 정치적 위선에 집중한 화가다.','과장된 얼굴과 잘린 공간, 신문 조각 같은 구성은 도시 권력의 혼란을 드러낸다. 군인·성직자·언론인을 잔혹한 캐리커처로 해부한 점은 그로스만의 특성이다.');
addNew('dada--berlin','artist-mid-john-heartfield','존 하트필드','John Heartfield',1891,1968,'독일','German','heartfield-adolf-superman','아돌프, 초인: 금을 삼키고 허튼소리를 내뱉다','Adolf, the Superman: Swallows Gold and Spouts Junk',1932,'1932','하트필드는 베를린 다다의 포토몽타주를 파시즘과 선전의 거짓을 폭로하는 정치적 무기로 발전시켰다.','사진 조각을 충돌시켜 그럴듯한 현실 이미지 안에 모순을 만든 점에서 다다의 비판성이 드러난다. 대중 잡지의 복제 방식을 역으로 이용한 점은 하트필드만의 특성이다.');
addNew('dada--new-york','artist-mid-francis-picabia','프란시스 피카비아','Francis Picabia',1879,1953,'프랑스','French','picabia-here-is-stieglitz','여기, 여기가 스티글리츠다','Here, This Is Stieglitz Here',1915,'1915','피카비아는 뉴욕 다다가 기계 도식을 인간 초상과 예술 제도의 풍자로 사용하는 방식을 보여 준다.','카메라와 기계 부품 같은 선이 인물을 대신해 전통적 초상의 기대를 무너뜨린다. 양식을 계속 바꾸며 일관된 작가 정체성 자체를 조롱한 점은 피카비아만의 특성이다.');
addNew('abstract-expressionism--action-painting','artist-mid-franz-kline','프란츠 클라인','Franz Kline',1910,1962,'미국','American','kline-chief','치프','Chief',1950,'1950','클라인은 액션 페인팅의 신체적 붓질을 흑백의 거대한 구조로 압축한 화가다.','검은 획이 흰 바탕을 가르며 제작 행위와 화면의 긴장을 동시에 드러낸다. 서예처럼 보이지만 작은 스케치를 확대해 충돌하는 건축적 힘으로 바꾼 점은 클라인만의 특성이다.');
addNew('abstract-expressionism--action-painting','artist-mid-lee-krasner','리 크래스너','Lee Krasner',1908,1984,'미국','American','krasner-the-seasons','계절','The Seasons',1957,'1957','크래스너는 액션 페인팅의 몸짓을 콜라주와 반복적인 자기 수정, 유기적 리듬으로 확장한 화가다.','큰 곡선과 겹치는 색이 화면 전체에서 움직여 전면적 구성이라는 사조의 특징을 드러낸다. 자신의 이전 작품을 잘라 다시 조립하며 변화 자체를 방법으로 삼은 점은 크래스너만의 특성이다.');
addNew('abstract-expressionism--color-field','artist-mid-clyfford-still','클리퍼드 스틸','Clyfford Still',1904,1980,'미국','American','still-1957-d-no-1','1957-D No. 1','1957-D No. 1',1957,'1957','스틸은 색면회화가 넓은 색의 장과 갈라진 가장자리만으로 숭고한 긴장을 만들 수 있음을 보여 준다.','거대한 색면이 수직으로 찢기듯 맞물려 관람자의 시야를 압도한다. 풍경이나 인물의 암시 없이 색을 지층과 불꽃 같은 힘으로 만든 점은 스틸만의 특성이다.');
addNew('abstract-expressionism--color-field','artist-mid-helen-frankenthaler','헬렌 프랭컨탤러','Helen Frankenthaler',1928,2011,'미국','American','frankenthaler-mountains-and-sea','산과 바다','Mountains and Sea',1952,'1952','프랭컨탤러는 색면회화의 넓은 장을 묽은 물감이 캔버스에 스며드는 방식으로 새롭게 열었다.','경계가 번지는 색 얼룩은 붓질과 바탕을 분리하지 않고 대기처럼 펼친다. 스테인 기법으로 다음 세대 색면 추상의 밝고 개방적인 공간을 만든 점은 프랭컨탤러만의 특성이다.');
addNew('pop-art--british','artist-mid-peter-blake','피터 블레이크','Peter Blake',1932,null,'영국','British','blake-on-the-balcony','발코니에서','On the Balcony',1957,'1955-1957','피터 블레이크는 영국 팝아트가 광고·잡지·팬 문화와 회화 전통을 한 화면에서 비교한 방식을 보여 준다.','대중 이미지와 미술 복제물이 나란히 놓여 고급문화와 대중문화의 경계를 흔든다. 수집가의 진열장 같은 세밀한 구성으로 영국적 향수와 소비문화를 결합한 점은 블레이크만의 특성이다.');
addNew('pop-art--british','artist-mid-david-hockney','데이비드 호크니','David Hockney',1937,null,'영국','British','hockney-a-bigger-splash','더 큰 첨벙','A Bigger Splash',1967,'1967','호크니는 영국 팝아트의 선명한 평면성과 대중 이미지를 캘리포니아의 현대 생활과 개인적 시선으로 확장했다.','평평한 건축과 강한 파랑, 물보라의 순간은 광고 같은 명료함과 회화적 시간을 함께 보여 준다. 인물이 없는 장면에 방금 일어난 사건과 욕망을 남긴 점은 호크니만의 특성이다.');
addNew('pop-art--american','artist-mid-claes-oldenburg','클라스 올덴버그','Claes Oldenburg',1929,2022,'스웨덴·미국','Swedish-American','oldenburg-floor-burger','바닥 햄버거','Floor Burger',1962,'1962','올덴버그는 미국 팝아트가 일상 소비재를 거대한 부드러운 조각으로 바꾸어 물건과 신체의 관계를 흔든 모습을 보여 준다.','익숙한 햄버거가 기념비적 크기와 처진 천으로 변해 소비문화의 과장과 유머를 드러낸다. 단단해야 할 조각을 부드럽고 불안정하게 만든 점은 올덴버그만의 특성이다.');
addNew('pop-art--american','artist-mid-james-rosenquist','제임스 로젠퀴스트','James Rosenquist',1933,2017,'미국','American','rosenquist-f-111','F-111','F-111',1965,'1964-1965','로젠퀴스트는 미국 팝아트의 광고판 기법으로 소비재와 군사 기술을 하나의 압도적 이미지 환경에 결합했다.','확대된 파편 이미지와 선명한 색은 대중매체의 시각적 충격을 드러낸다. 자동차·스파게티·폭격기를 끊김 없이 연결해 풍요와 전쟁의 공존을 비판한 점은 로젠퀴스트만의 특성이다.');
addNew('postmodernism--appropriation-pictures','artist-mid-barbara-kruger','바버라 크루거','Barbara Kruger',1945,null,'미국','American','kruger-your-body-battleground','당신의 몸은 전쟁터다','Untitled (Your Body Is a Battleground)',1989,'1989','크루거는 차용미술이 광고의 사진과 문구를 이용해 성별·권력·소비의 언어를 비판하는 방식을 보여 준다.','흑백 얼굴 위의 붉고 흰 문장은 대중매체의 즉각적인 설득 방식을 그대로 사용한다. 관람자를 당신이라고 직접 부르며 이미지 소비의 책임을 되돌린 점은 크루거만의 특성이다.');
addNew('postmodernism--neo-expressionism','artist-mid-georg-baselitz','게오르크 바젤리츠','Georg Baselitz',1938,null,'독일','German','baselitz-the-wood-on-its-head','거꾸로 선 숲','The Wood on Its Head',1969,'1969','바젤리츠는 신표현주의가 전후 독일의 기억과 거친 회화성을 뒤집힌 형상으로 다시 다룬 선구적 화가다.','인물을 거꾸로 놓아 서사보다 물감과 붓질을 먼저 보게 하는 점에서 회화의 물질성이 드러난다. 익숙한 독일적 모티프를 불편하고 분열된 이미지로 만든 점은 바젤리츠만의 특성이다.');
addNew('futurism--italian','artist-mid-carlo-carra','카를로 카라','Carlo Carra',1881,1966,'이탈리아','Italian','carra-funeral-anarchist-galli','무정부주의자 갈리의 장례식','The Funeral of the Anarchist Galli',1911,'1910-1911','카라는 이탈리아 미래주의가 군중의 충돌과 정치적 폭력을 반복되는 선과 면으로 표현한 방식을 보여 준다.','휘어지는 곤봉과 붉은 깃발, 겹친 인물은 사건의 속도와 충격을 한 화면에 압축한다. 실제 기억을 입체주의적 분절과 집단 운동으로 재구성한 점은 카라만의 특성이다.');
addNew('futurism--italian','artist-mid-gino-severini','지노 세베리니','Gino Severini',1883,1966,'이탈리아·프랑스 활동','Italian, active in France','severini-dynamic-hieroglyph-bal-tabarin','발 타바랭의 역동적 상형문자','Dynamic Hieroglyph of the Bal Tabarin',1912,'1912','세베리니는 미래주의의 속도와 동시성을 파리의 춤·조명·대중 오락에 적용한 화가다.','분절된 무용수와 반복되는 색면이 음악과 움직임을 동시에 전달한다. 이탈리아 미래주의와 프랑스 입체주의를 국제적인 도시 리듬으로 연결한 점은 세베리니만의 특성이다.');
addNew('futurism--russian-cubo','artist-mid-mikhail-larionov','미하일 라리오노프','Mikhail Larionov',1881,1964,'러시아','Russian','larionov-rayonist-sausages-mackerel','소시지와 고등어의 광선주의 정물','Rayonist Sausages and Mackerel',1912,'1912','라리오노프는 러시아 입체미래주의가 대상의 외형을 빛의 교차와 에너지로 해체하는 광선주의로 나아간 모습을 보여 준다.','날카로운 색선이 사물을 가로질러 속도와 빛의 충돌을 드러낸다. 민속적 색채와 서유럽 전위 기법을 결합해 러시아 고유의 추상을 모색한 점은 라리오노프만의 특성이다.');
addKnown('bauhaus--core','artist-art-atlas-kandinsky',{id:'kandinsky-yellow-red-blue',title:{ko:'노랑-빨강-파랑',en:'Yellow-Red-Blue'},year:1925,yearLabel:'1925'},'칸딘스키는 청기사파에서 발전한 추상 색채 이론을 바우하우스의 체계적인 조형 교육으로 연결했다.','기하학적 형태와 자유로운 선, 노랑·빨강·파랑의 관계가 긴장과 리듬을 만드는 점에서 바우하우스의 기초 조형 연구가 드러난다. 정신적 추상을 분석 가능한 교육 언어로 정리한 점은 칸딘스키만의 특성이다.',{otherMovements:['청기사파'],duplicateArtistReason:'칸딘스키는 청기사파의 정신적 추상을 바우하우스의 색·형태 교육으로 연결한 핵심 화가다.'});
addNew('bauhaus--core','artist-mid-laszlo-moholy-nagy','라슬로 모호이너지','Laszlo Moholy-Nagy',1895,1946,'헝가리·독일 활동','Hungarian, active in Germany','moholy-nagy-light-space-modulator','빛-공간 변조기','Light-Space Modulator',1930,'1922-1930','모호이너지는 바우하우스가 회화에서 사진·타이포그래피·기계·빛으로 교육 범위를 넓힌 중심 인물이다.','회전하는 금속과 투명 재료가 빛과 그림자를 계속 바꾸어 기술과 시각 실험의 결합을 보여 준다. 매체 구분보다 새로운 시각 교육을 앞세운 점은 모호이너지만의 특성이다.');
addNew('bauhaus--core','artist-mid-anni-albers','아니 알버스','Anni Albers',1899,1994,'독일·미국','German-American','albers-wall-hanging','벽걸이','Wall Hanging',1926,'1925-1926','아니 알버스는 바우하우스의 기하학과 기능주의를 직조의 재료·구조·촉각으로 확장한 핵심 디자이너다.','반복되는 격자와 색실의 관계는 추상 조형과 실용 직물이 분리되지 않음을 보여 준다. 주변화된 직조 공방을 현대 디자인과 건축의 실험실로 바꾼 점은 알버스만의 특성이다.');
addNew('surrealism--automatist','artist-mid-max-ernst','막스 에른스트','Max Ernst',1891,1976,'독일·프랑스','German-French','ernst-two-children-threatened-nightingale','나이팅게일에게 위협받는 두 아이','Two Children Are Threatened by a Nightingale',1924,'1924','에른스트는 초현실주의의 우연한 이미지와 꿈의 논리를 콜라주·프로타주·오브제로 확장한 화가다.','회화 표면에 실제 문과 울타리를 붙여 꿈과 현실의 경계를 깨뜨린다. 재료의 우연한 무늬에서 낯선 생물과 풍경을 발견한 점은 에른스트만의 특성이다.');
addNew('surrealism--automatist','artist-mid-roberto-matta','로베르토 마타','Roberto Matta',1911,2002,'칠레','Chilean','matta-inscape-psychological-morphology','심리적 형태학','Inscape: Psychological Morphology',1938,'1938','마타는 자동기술적 초현실주의를 무한히 열리는 심리적 공간과 에너지의 장으로 확장했다.','떠다니는 선과 반투명 색면이 고정된 대상 없이 내면의 움직임을 보여 준다. 건축적 공간 감각을 무의식의 우주로 바꾸어 추상표현주의에 연결한 점은 마타만의 특성이다.');
addNew('surrealism--illusionistic','artist-mid-yves-tanguy','이브 탕기','Yves Tanguy',1900,1955,'프랑스·미국','French-American','tanguy-indefinite-divisibility','무한한 분할 가능성','Indefinite Divisibility',1942,'1942','탕기는 환영적 초현실주의가 사실적인 원근과 그림자를 존재하지 않는 생물 형태에 적용한 모습을 보여 준다.','끝없는 지평선과 정체불명의 물체가 꿈의 공간을 실제 풍경처럼 설득력 있게 만든다. 제한된 색과 매끈한 표면으로 고요하면서 불안한 세계를 반복한 점은 탕기만의 특성이다.');
addNew('surrealism--illusionistic','artist-mid-leonora-carrington','레오노라 캐링턴','Leonora Carrington',1917,2011,'영국·멕시코','British-Mexican','carrington-self-portrait-inn-dawn-horse','자화상: 여명의 말 여관','Self-Portrait (Inn of the Dawn Horse)',1938,'1937-1938','캐링턴은 초현실주의의 변신과 신화를 여성 주체의 자전적 세계로 다시 구성한 화가다.','하이에나와 말, 떠 있는 머리카락은 꿈의 논리와 변신이라는 초현실주의의 특징을 드러낸다. 여성을 수동적 뮤즈가 아니라 마법과 서사를 통제하는 주인공으로 만든 점은 캐링턴만의 특성이다.');
addNew('mexican-muralism--core','artist-mid-siqueiros','다비드 알파로 시케이로스','David Alfaro Siqueiros',1896,1974,'멕시코','Mexican','siqueiros-portrait-bourgeoisie','부르주아지의 초상','Portrait of the Bourgeoisie',1940,'1939-1940','시케이로스는 멕시코 벽화운동의 혁명적 메시지를 산업 재료와 영화적 원근으로 밀어붙인 화가다.','급격한 단축과 소용돌이치는 기계 이미지는 공공 벽화의 선동적 힘을 드러낸다. 스프레이건과 합성 도료를 사용해 현대 기술을 정치적 집단 제작에 결합한 점은 시케이로스만의 특성이다.');
addNew('social-realism--core','artist-mid-jacob-lawrence','제이컵 로런스','Jacob Lawrence',1917,2000,'미국','American','lawrence-migration-series-panel-1','이주 연작 1번','The Migration Series, Panel 1',1941,'1940-1941','로런스는 미국 사회적 사실주의가 흑인 대이동의 집단 역사를 연속된 현대 서사로 기록한 모습을 보여 준다.','단순한 형상과 반복되는 색면이 많은 사람의 이동을 명료하고 리듬 있게 전달한다. 개인 영웅 대신 공동체의 경험을 60개 패널의 시각적 문장으로 만든 점은 로런스만의 특성이다.');
addNew('socialist-realism--core','artist-mid-isaak-brodsky','이사크 브로츠키','Isaak Brodsky',1883,1939,'러시아·소련','Russian-Soviet','brodsky-lenin-smolny','스몰니의 레닌','Lenin in Smolny',1930,'1930','브로츠키는 사회주의적 사실주의가 혁명 지도자의 이미지를 사실적이고 권위 있는 국가 표상으로 정착시킨 과정을 보여 준다.','정돈된 사무실과 집중한 자세는 지도자를 근면하고 절제된 인물로 제시한다. 아카데미식 정밀함을 정치적 정통성의 이미지로 전환한 점은 브로츠키만의 특성이다.');
addNew('art-informel--core','artist-mid-hans-hartung','한스 아르퉁','Hans Hartung',1904,1989,'독일·프랑스','German-French','hartung-t1947-20','T1947-20','T1947-20',1947,'1947','아르퉁은 앵포르멜의 즉흥적 선과 행위성을 빠르고 날카로운 검은 획으로 대표한 화가다.','긁고 휘두른 선이 고정된 형상 없이 긴장과 속도를 남겨 비정형 추상의 특징을 드러낸다. 실제 몸짓을 스케치와 확대 과정을 통해 정밀하게 통제한 점은 아르퉁만의 특성이다.');
addNew('art-informel--core','artist-mid-pierre-soulages','피에르 술라주','Pierre Soulages',1919,2022,'프랑스','French','soulages-painting-195-130-1953','회화 195 x 130 cm, 1953','Painting 195 x 130 cm, 1953',1953,'1953','술라주는 앵포르멜의 물질성과 몸짓을 검은색이 빛을 반사하는 구조로 발전시킨 화가다.','넓고 거친 검은 획 사이로 바탕의 빛이 드러나 형상 없이 깊이와 리듬을 만든다. 검정을 어둠이 아니라 빛을 변화시키는 재료로 다룬 점은 술라주만의 특성이다.');
addNew('nouveau-realisme--core','artist-mid-jean-tinguely','장 팅겔리','Jean Tinguely',1925,1991,'스위스','Swiss','tinguely-homage-new-york','뉴욕에 바치는 경의','Homage to New York',1960,'1960','팅겔리는 누보 레알리슴이 산업 폐기물과 기계의 실제 움직임을 일회적 사건으로 사용하는 방식을 보여 준다.','조립된 기계가 움직이고 소리를 내다 스스로 파괴되어 완성된 물체보다 현실의 사건을 앞세운다. 기능 없는 기계에 유머와 실패를 부여한 점은 팅겔리만의 특성이다.');
addNew('nouveau-realisme--core','artist-mid-niki-de-saint-phalle','니키 드 생팔','Niki de Saint Phalle',1930,2002,'프랑스·미국','French-American','saint-phalle-shooting-picture','사격 회화','Shooting Picture',1961,'1961','생팔은 누보 레알리슴의 실제 행위와 재료를 사격 퍼포먼스와 여성 신체의 정치성으로 확장했다.','관객이 석고 표면을 쏘면 숨은 물감이 흘러 작품이 우연히 완성된다. 파괴 행위를 공동 제작과 사회 규범에 대한 공격으로 바꾼 점은 생팔만의 특성이다.');
addNew('minimalism--core','artist-mid-carl-andre','칼 안드레','Carl Andre',1935,2024,'미국','American','andre-equivalent-viii','등가물 VIII','Equivalent VIII',1966,'1966','안드레는 미니멀리즘이 조각을 받침대 위 물체가 아니라 바닥과 관람자의 이동 관계로 바꾼 모습을 보여 준다.','같은 벽돌을 규칙적으로 배열해 작가의 손과 환영을 줄이고 재료·수량·장소를 직접 드러낸다. 조각의 수직 기념비성을 수평의 장소 경험으로 전환한 점은 안드레만의 특성이다.');
addNew('minimalism--core','artist-mid-robert-morris','로버트 모리스','Robert Morris',1931,2018,'미국','American','morris-untitled-l-beams','무제(L자 빔)','Untitled (L-Beams)',1965,'1965','모리스는 미니멀리즘의 단순한 형태가 관람자의 몸과 공간에 따라 다르게 지각된다는 점을 이론과 작품으로 보여 준다.','같은 L자 구조 세 개가 방향에 따라 서로 다른 물체처럼 보여 형태보다 경험의 조건을 드러낸다. 조각을 고정된 의미가 아닌 신체적 지각의 문제로 만든 점은 모리스만의 특성이다.');
addNew('minimalism--core','artist-mid-agnes-martin','애그니스 마틴','Agnes Martin',1912,2004,'캐나다·미국','Canadian-American','martin-the-tree','나무','The Tree',1964,'1964','마틴은 미니멀리즘의 반복 격자를 손으로 그은 미세한 차이와 명상적 감정으로 확장했다.','옅은 연필선과 제한된 색이 거의 비어 있는 화면에 조용한 리듬을 만든다. 산업적 완벽함보다 손의 흔들림과 내적 평온을 남긴 점은 마틴만의 특성이다.');
addNew('conceptual-art--idea-language','artist-mid-sol-lewitt','솔 르윗','Sol LeWitt',1928,2007,'미국','American','lewitt-wall-drawing-51','벽 드로잉 51','Wall Drawing 51',1970,'1970','르윗은 개념미술에서 작품의 핵심이 작가가 직접 만든 물체가 아니라 실행 가능한 지시와 체계라는 점을 확립했다.','문장으로 된 규칙을 다른 사람이 벽에 실행할 수 있어 아이디어가 물질보다 우선한다. 저자성을 설계와 실행으로 분리한 점은 르윗만의 특성이다.');
addNew('conceptual-art--idea-language','artist-mid-on-kawara','온 가와라','On Kawara',1932,2014,'일본','Japanese','kawara-today-series','오늘 연작','Today Series',1966,'1966-2014','온 가와라는 개념미술이 날짜와 존재의 기록만으로 시간·장소·삶의 조건을 다룰 수 있음을 보여 준다.','그날의 날짜만 정확한 서체로 그려 작품을 정보와 사건의 증거로 만든다. 제작하지 못한 날의 캔버스는 폐기하는 엄격한 규칙으로 개인의 삶을 보편적 시간 체계에 연결한 점은 가와라만의 특성이다.');
addNew('conceptual-art--fluxus','artist-mid-george-maciunas','조지 마치우나스','George Maciunas',1931,1978,'리투아니아·미국','Lithuanian-American','maciunas-fluxus-manifesto','플럭서스 선언','Fluxus Manifesto',1963,'1963','마치우나스는 플럭서스를 국제적 네트워크와 출판·행사 형식으로 조직해 예술과 일상의 경계를 흔든 인물이다.','값싼 인쇄물과 명령문, 공동 행사는 독창적 명품보다 공유 가능한 아이디어를 앞세운다. 여러 작가의 느슨한 활동을 유통 체계와 시각 정체성으로 묶은 점은 마치우나스만의 특성이다.');
addNew('contemporary-art--installation-performance','artist-mid-allan-kaprow','앨런 캐프로','Allan Kaprow',1927,2006,'미국','American','kaprow-18-happenings-6-parts','여섯 부분으로 된 18개의 해프닝','18 Happenings in 6 Parts',1959,'1959','캐프로는 설치와 퍼포먼스가 관객의 이동·행동·시간으로 이루어지는 해프닝 형식을 확립했다.','분리된 공간에서 정해진 신호에 따라 관객과 행위자가 움직여 작품이 하나의 상황으로 존재한다. 회화의 환경을 실제 생활 사건으로 확장한 점은 캐프로만의 특성이다.');
addNew('contemporary-art--installation-performance','artist-mid-yayoi-kusama','구사마 야요이','Yayoi Kusama',1929,null,'일본','Japanese','kusama-infinity-mirror-room','무한 거울 방','Infinity Mirror Room',1965,'1965','구사마는 반복 무늬와 거울 설치를 통해 개인적 강박을 관람자가 들어가는 무한 공간으로 확장했다.','거울과 반복되는 빛·물체가 몸의 경계를 흩뜨려 설치미술의 몰입적 경험을 만든다. 자전적 환각을 대중이 공유하는 환경으로 바꾼 점은 구사마만의 특성이다.');
addNew('contemporary-art--new-media-digital','artist-mid-bill-viola','빌 비올라','Bill Viola',1951,2024,'미국','American','viola-the-crossing','교차','The Crossing',1996,'1996','비올라는 비디오의 느린 시간과 대형 투사를 통해 물·불·탄생·죽음을 명상적 설치 경험으로 만든 작가다.','인물이 극도로 느리게 물과 불에 휩싸이며 영상의 시간 자체가 관람의 주제가 된다. 첨단 매체를 오래된 종교화처럼 집중적인 감정 경험으로 바꾼 점은 비올라만의 특성이다.');
addNew('contemporary-art--new-media-digital','artist-mid-lynn-hershman-leeson','린 허시먼 리슨','Lynn Hershman Leeson',1941,null,'미국','American','hershman-robberta-breitmore','로버타 브라이트모어','Roberta Breitmore',1974,'1973-1978','허시먼 리슨은 뉴미디어와 퍼포먼스를 이용해 가상 정체성·감시·기술 속 여성 주체를 일찍부터 탐구한 작가다.','가공의 인물이 실제 계좌와 광고, 사회관계를 갖게 되어 현실과 데이터 정체성의 경계를 흔든다. 관객 상호작용과 네트워크를 작품 구조로 삼은 점은 허시먼 리슨만의 특성이다.');
addNew('contemporary-art--street-participatory','artist-mid-keith-haring','키스 해링','Keith Haring',1958,1990,'미국','American','haring-crack-is-wack','크랙은 끝장이다','Crack Is Wack',1986,'1986','해링은 거리미술의 단순한 기호와 반복 선을 공공 보건·인권 메시지에 결합한 화가다.','굵은 윤곽과 즉시 읽히는 인물이 도시 벽면에서 빠르게 소통해 거리미술의 대중성을 드러낸다. 미술관과 지하철·공공 벽화를 오가며 사회운동의 시각 언어를 만든 점은 해링만의 특성이다.');
addNew('contemporary-art--street-participatory','artist-mid-ai-weiwei','아이 웨이웨이','Ai Weiwei',1957,null,'중국','Chinese','ai-sunflower-seeds','해바라기 씨','Sunflower Seeds',2010,'2010','아이 웨이웨이는 설치와 참여, 디지털 소통을 통해 대량생산·국가 권력·개인의 목소리를 함께 다루는 작가다.','수많은 수제 도자기 씨앗은 집단과 개인, 수공예와 대량생산의 모순을 체험하게 한다. 작품 제작과 사회적 발언을 분리하지 않고 공론장으로 확장한 점은 아이 웨이웨이만의 특성이다.');

const representatives = JSON.parse(fs.readFileSync(representativesFile, 'utf8'));
const previousWorkMetadata = new Map((representatives.furtherArtists || []).flatMap(category => (category.artists || []).map(item => [
  `${item.artist.id}|${item.work.id}`,
  item.work
])));
entries.forEach(category => category.artists.forEach(item => {
  const previous = previousWorkMetadata.get(`${item.artist.id}|${item.work.id}`);
  if (!previous) return;
  ['localImage','sourceUrl','license','institution'].forEach(key => {
    if (previous[key]) item.work[key] = previous[key];
  });
}));
const expected = new Set(representatives.categories.map(entry => entry.categoryId));
if (entries.length !== expected.size || entries.some(entry => !expected.has(entry.categoryId))) {
  throw new Error(`Expected ${expected.size} further-artist categories, got ${entries.length}`);
}
const duplicateReasonByArtist = new Map([
  ['artist-art-atlas-picasso','피카소는 분석적 입체주의의 형성과 종합적 입체주의의 확장 모두를 설명하는 핵심 화가다.'],
  ['artist-art-atlas-malevich','말레비치는 러시아 입체미래주의의 형식 실험을 절대주의의 순수 기하학으로 전환한 연결 인물이다.'],
  ['artist-art-atlas-klimt','클림트는 중부유럽 상징주의와 빈 분리파의 장식적 현대성을 함께 대표한다.'],
  ['artist-art-atlas-kandinsky','칸딘스키는 청기사파의 정신적 추상을 바우하우스의 색·형태 교육으로 연결한 핵심 화가다.'],
  ['artist-art-atlas-paik','백남준은 플럭서스의 참여적 사건을 비디오와 전자 매체로 확장해 뉴미디어 미술로 연결한 핵심 작가다.']
]);
const otherMovementsByArtist = new Map([
  ['artist-art-atlas-picasso',['종합적 입체주의']],
  ['artist-art-atlas-malevich',['러시아 입체미래주의·구성주의']],
  ['artist-art-atlas-klimt',['상징주의']],
  ['artist-art-atlas-kandinsky',['바우하우스']],
  ['artist-art-atlas-paik',['뉴미디어·디지털 아트']]
]);
representatives.categories.forEach(entry => {
  const reason = duplicateReasonByArtist.get(entry.artist.id);
  if (reason) entry.duplicateArtistReason = reason;
  const otherMovements = otherMovementsByArtist.get(entry.artist.id);
  if (otherMovements) entry.otherMovements = otherMovements;
});
representatives.schema = 2;
representatives.status = 'further-artists-complete';
representatives.policy.expansion = '각 정본 범주는 대표 화가 1명 뒤에 중급 확장을 위한 더 볼 화가 1~4명을 둔다.';
representatives.policy.furtherArtistDescription = '더 볼 화가 설명은 작품에서 드러나는 해당 사조의 특징과 화가만의 고유 특성을 함께 밝힌다.';
representatives.policy.crossMovement = '여러 사조에 걸친 화가는 각 사조에 모두 두고 카드에 다른 소속 사조를 명시한다.';
representatives.policy.missingImageLabel = '로컬 이미지가 없으면 외부 URL을 만들지 않고 다운로드 필요로 표시한다.';
representatives.furtherArtists = entries;
fs.writeFileSync(representativesFile, `${JSON.stringify(representatives, null, 2)}\n`, 'utf8');
